package mapping

import (
	"reflect"
	"sync"
	"unsafe"

	"github.com/smatify/smorm/internal/entity"
)

// Accessor reads and writes the fields of one entity type. Field and
// association indexes refer to Entity.Fields and Entity.Assocs. Join column
// fields (Field.Name == "") have no Go storage and must not be passed.
//
// Code generated by the smorm generator implements Accessor without
// reflection; otherwise a reflection based implementation is used.
type Accessor interface {
	// New allocates a zero entity and returns a pointer to it.
	New() any
	// Header returns the embedded entity header of ptr.
	Header(ptr any) *entity.Header
	// Get returns the value of field i.
	Get(ptr any, i int) any
	// Set assigns v (of the field's exact Go type, or nil for the zero value) to field i.
	Set(ptr any, i int, v any)
	// Addr returns a pointer to field i, suitable as a scan destination.
	Addr(ptr any, i int) any
	// GetAssoc returns the value of association field i.
	GetAssoc(ptr any, i int) any
	// AssocAddr returns a pointer to association field i.
	AssocAddr(ptr any, i int) any
}

var (
	generatedMu sync.RWMutex
	generated   = map[reflect.Type]Accessor{}
)

// RegisterAccessor installs a generated accessor for the struct type t. It is
// called from init functions in generated files.
func RegisterAccessor(t reflect.Type, a Accessor) {
	generatedMu.Lock()
	defer generatedMu.Unlock()
	generated[t] = a
}

// Accessor returns the generated accessor for e if one is registered, or a
// reflection based one.
func (e *Entity) Accessor() Accessor {
	e.accessorOnce.Do(func() {
		generatedMu.RLock()
		a, ok := generated[e.GoType]
		g, okG := generatedTypes[e.GoType]
		generatedMu.RUnlock()
		switch {
		case ok:
			e.accessor = a
			e.Generated = true
			return
		case okG:
			e.accessor = newComposedAccessor(e, g)
			e.Generated = true
			return
		}
		e.accessor = &reflectAccessor{e: e}
	})
	return e.accessor
}

type reflectAccessor struct{ e *Entity }

// fieldValue returns an addressable, settable value for the field at index,
// including unexported fields.
func fieldValue(ptr any, index []int) reflect.Value {
	v := reflect.ValueOf(ptr).Elem().FieldByIndex(index)
	if !v.CanSet() {
		v = reflect.NewAt(v.Type(), unsafe.Pointer(v.UnsafeAddr())).Elem()
	}
	return v
}

func (a *reflectAccessor) New() any { return reflect.New(a.e.GoType).Interface() }

func (a *reflectAccessor) Header(ptr any) *entity.Header {
	return fieldValue(ptr, a.e.HeaderIndex).Addr().Interface().(*entity.Header)
}

func (a *reflectAccessor) field(i int) *Field {
	f := a.e.Fields[i]
	if f.Index == nil {
		panic("mapping: join column " + f.Column + " has no Go field")
	}
	return f
}

func (a *reflectAccessor) Get(ptr any, i int) any {
	return fieldValue(ptr, a.field(i).Index).Interface()
}

func (a *reflectAccessor) Set(ptr any, i int, v any) {
	fv := fieldValue(ptr, a.field(i).Index)
	if v == nil {
		fv.SetZero()
		return
	}
	fv.Set(reflect.ValueOf(v))
}

func (a *reflectAccessor) Addr(ptr any, i int) any {
	return fieldValue(ptr, a.field(i).Index).Addr().Interface()
}

func (a *reflectAccessor) GetAssoc(ptr any, i int) any {
	return fieldValue(ptr, a.e.Assocs[i].Index).Interface()
}

func (a *reflectAccessor) AssocAddr(ptr any, i int) any {
	return fieldValue(ptr, a.e.Assocs[i].Index).Addr().Interface()
}
